 let owner=state.db.register_auth_user("smart-owner","public synthetic password").await.unwrap().unwrap();let outsider=state.db.register_auth_user("smart-outsider","public synthetic password").await.unwrap().unwrap();let space=state.db.create_space("smart-owner","Smart clip").await.unwrap();
